.ds {
  color:var(--p-ink); background:var(--p-bg); font:var(--p-type-body);
  color-scheme:light; word-break:keep-all; overflow-wrap:anywhere; text-align:left;
}
.ds,.ds * { box-sizing:border-box; }
.ds [hidden] { display:none!important; }
.ds :is(h1,h2,h3,p,fieldset) { margin:0; }
.ds :is(button,input,select,textarea) { font:inherit; color:inherit; letter-spacing:inherit; }
.ds :is(code,pre) { font-family:var(--p-mono-font); }
.ds button { cursor:pointer; touch-action:manipulation; }
.ds button:disabled { cursor:not-allowed; }
.ds :is(button,input,select,textarea,a,[tabindex]):focus-visible { outline:var(--p-border-width-focus) solid var(--p-highlight); outline-offset:var(--p-focus-offset); }
.ds .ui-icon { display:inline-block; width:var(--p-icon-lg); height:var(--p-icon-lg); object-fit:contain; flex-shrink:0; vertical-align:middle; }
.ds .ds-demo-note { font-size:var(--p-text-sm); margin-top:var(--p-space-sm); min-height:calc(var(--p-space-unit) * 5); color:var(--p-muted); }
.ds .ds-surface { border:var(--p-border-width) solid var(--p-line); border-radius:var(--p-radius); background:var(--p-surface); }
.ds .ds-surface[data-material="raised"] { box-shadow:var(--p-shadow); border-color:var(--p-edge); }
.ds .ds-surface[data-material="inset"] { box-shadow:var(--p-inset); background:var(--p-bg); }
.ds .ds-surface[data-material="glass"] { background:var(--p-high); box-shadow:var(--p-glass-shadow); }
@supports (backdrop-filter:blur(0)) { .ds .ds-surface[data-material="glass"] { background:var(--p-glass); backdrop-filter:var(--p-blur-md); } }
@media(prefers-reduced-transparency:reduce) { .ds .ds-surface[data-material="glass"] { background:var(--p-high); backdrop-filter:none; } }
@media(prefers-reduced-motion:reduce) { .ds * { transition:none!important; animation:none!important; } }
.ds .ds-token-row { display:flex; flex-wrap:wrap; align-items:center; gap:var(--p-space-sm); }
.ds .ds-admin-error { color:var(--p-error); font-size:var(--p-text-body); }

/* the record detail that a result opens, with its way back and its main action */
.ds .ds-record-detail { padding:var(--p-space-lg); border:var(--p-border-width) solid var(--p-line); border-radius:var(--p-radius); background:var(--p-surface); }
.ds .ds-record-detail h3 { font-size:var(--p-text-lg); font-weight:var(--p-weight-semibold); }
.ds .ds-record-detail p { margin-top:var(--p-space-sm); color:var(--p-muted); }
.ds .ds-record-detail > div { display:flex; flex-wrap:wrap; gap:var(--p-space-sm); margin-top:var(--p-space-lg); }
.ds .ds-record-detail [aria-pressed="true"] { background:var(--p-success); border-color:var(--p-success); }

.ds .ds-page { max-width:var(--p-container-xl); margin-inline:auto; }
.ds .ds-page-header { display:flex; justify-content:space-between; align-items:center; gap:var(--p-space-md); margin-bottom:var(--p-space-xl); }
.ds .ds-page-header h2 { font-size:var(--p-text-heading); font-weight:var(--p-weight-semibold); letter-spacing:var(--p-tracking-tighter); margin-top:var(--p-space-xs); }
.ds .ds-eyebrow { font-size:var(--p-text-sm); color:var(--p-muted); }
.ds .ds-page > .ds-bottom-nav { margin:var(--p-space-xl) auto 0; max-width:var(--p-container-md); }
/* Looks: how the screen opens. Each look also brings its own bottom bar shape from the markup. */
.ds .ds-page[data-look="hero"] .ds-page-header { align-items:flex-end; padding:calc(var(--p-space-unit) * 7) calc(var(--p-space-unit) * 5) calc(var(--p-space-unit) * 5); border-radius:var(--p-radius); background:var(--p-soft); }
.ds .ds-page[data-look="hero"] .ds-page-header h2 { font-size:var(--p-text-display); line-height:var(--p-leading-tight); }
.ds .ds-page[data-look="appbar"] .ds-page-header { position:relative; justify-content:center; padding:var(--p-space-2xs) var(--p-space-4xl) var(--p-space-md); margin-bottom:var(--p-space-lg); border-bottom:var(--p-border-width) solid var(--p-line); text-align:center; }
.ds .ds-page[data-look="appbar"] .ds-page-header h2 { margin-top:0; font-size:var(--p-text-title); letter-spacing:var(--p-tracking-tight); }
.ds .ds-page[data-look="appbar"] .ds-page-header > .ds-badge { position:absolute; right:0; top:50%; translate:0 calc(100% * 3 / 5 * -1); }
.ds .ds-page[data-look="sheet"] .ds-page-header { align-items:flex-start; margin-bottom:0; padding:var(--p-space-lg) calc(var(--p-space-unit) * 5) var(--p-space-4xl); border-radius:var(--p-radius) var(--p-radius) 0 0; background:var(--p-accent); color:var(--p-on-accent); }
.ds .ds-page[data-look="sheet"] .ds-page-header .ds-eyebrow { color:var(--p-on-accent-muted); }
.ds .ds-page[data-look="sheet"] .ds-page-header + * { position:relative; margin-top:calc(var(--p-space-xl) * -1); padding:var(--p-space-lg) calc(var(--p-space-unit) * 5); border-radius:var(--p-radius-2xl) var(--p-radius-2xl) 0 0; background:var(--p-high); }
.ds .ds-page[data-look="dashboard"] .ds-page-header { margin-bottom:var(--p-space-md); }
.ds .ds-template-slot { min-height:calc(var(--p-space-unit) * 40); display:grid; place-items:center; padding:var(--p-space-lg); border:var(--p-border-width) var(--p-stroke-dashed) var(--p-control-border); border-radius:var(--p-radius); color:var(--p-muted); font-size:var(--p-text-body); }

.ds .ds-badge { display:inline-flex; align-items:center; width:fit-content; padding:var(--p-space-2xs) var(--p-space-xs); border:var(--p-border-width) solid var(--p-line); border-radius:var(--p-radius-full); background:var(--p-soft); color:var(--p-ink); font-size:var(--p-text-sm); line-height:var(--p-leading-normal); font-weight:var(--p-weight-semibold); }
.ds .ds-badge[data-tone="success"] { background:var(--p-success-soft); border-color:var(--p-success-line); color:var(--p-success); }
.ds .ds-badge[data-tone="error"] { background:var(--p-error-soft); border-color:var(--p-error-line); color:var(--p-error); }
.ds .ds-badge[data-tone="warning"] { background:var(--p-warning-soft); border-color:var(--p-warning-line); color:var(--p-warning); }
/* looks: tone keeps the color, look changes the surface */
.ds .ds-badge[data-look="icon"] { gap:var(--p-space-2xs); padding-left:var(--p-space-xs); }
.ds .ds-badge[data-look="icon"] .ui-icon { width:var(--p-icon-sm); height:var(--p-icon-sm); }

.ds .ds-page-stats { display:grid; grid-template-columns:repeat(3,minmax(0,1fr)); gap:var(--p-space-xs); margin:0 0 var(--p-space-lg); padding:0; list-style:none; }
.ds .ds-page-stats li { display:grid; gap:var(--p-space-3xs); padding:var(--p-space-sm); border:var(--p-border-width) solid var(--p-line); border-radius:var(--p-radius-xl); background:var(--p-surface); }
.ds .ds-page-stats strong { font:var(--p-type-stat); letter-spacing:var(--p-tracking-tight); }
.ds .ds-page-stats span { font-size:var(--p-text-sm); color:var(--p-muted); }

.ds .ds-search-module { container-type:inline-size; }
.ds .ds-search-form { display:grid; grid-template-columns:minmax(0,1fr) minmax(calc(var(--p-space-unit) * 22),.3fr) auto; align-items:end; gap:var(--p-space-sm); }
@media(max-width:580px) { .ds .ds-search-form { grid-template-columns:minmax(0,1fr) auto; } .ds .ds-search-form > .ds-field { grid-column:1/-1; } }
@container(max-width:580px) { .ds .ds-search-form { grid-template-columns:minmax(0,1fr) auto; } .ds .ds-search-form > .ds-field { grid-column:1/-1; } }

.ds .ds-field,.ds .ds-select-field { display:grid; gap:var(--p-space-xs); min-width:0; font-size:var(--p-text-body); }
.ds .ds-field > label,.ds .ds-select-field > span { font-weight:var(--p-weight-semibold); }
.ds .ds-help { font-size:var(--p-text-sm); color:var(--p-muted); line-height:var(--p-leading-normal); }
.ds .ds-field[data-state="error"] .ds-help { color:var(--p-error); }
.ds .ds-field[data-state="error"] .ds-help::before { content:'!'; display:inline-grid; place-items:center; width:var(--p-size-md); height:var(--p-size-md); font-size:var(--p-text-sm); border:var(--p-border-width) solid currentColor; border-radius:var(--p-radius-circle); margin-right:var(--p-space-2xs); }
.ds .ds-field[data-state="success"] .ds-help { color:var(--p-success); }
.ds .ds-field[data-state="success"] .ds-help::before { content:'✓'; margin-right:var(--p-space-2xs); }
.ds .ds-field[data-state="success"] .ds-input { border-color:var(--p-success); }
.ds .ds-field[data-state="focus"] .ds-input { outline:var(--p-border-width-focus) solid var(--p-highlight); outline-offset:var(--p-focus-offset); }

.ds .ds-input { display:block; width:100%; min-width:0; min-height:var(--p-control-size-md); padding:var(--p-space-sm) var(--p-space-md); border:var(--p-border-width) solid var(--p-control-border); border-radius:var(--p-control-radius); background:var(--p-bg); box-shadow:var(--p-inset); color:var(--p-ink); font-size:var(--p-text-body); line-height:var(--p-leading-normal); }
.ds select.ds-input { appearance:none; padding-inline-end:calc(var(--p-space-md) * 2 + var(--p-size-2xs)); background-image:linear-gradient(45deg,transparent calc(50% - var(--p-border-width)),var(--p-muted) calc(50% - var(--p-border-width)) calc(50% + var(--p-border-width)),transparent calc(50% + var(--p-border-width))),linear-gradient(-45deg,transparent calc(50% - var(--p-border-width)),var(--p-muted) calc(50% - var(--p-border-width)) calc(50% + var(--p-border-width)),transparent calc(50% + var(--p-border-width))); background-size:calc(var(--p-size-2xs) + var(--p-space-3xs)) calc(var(--p-size-2xs) + var(--p-space-3xs)); background-position:calc(100% - var(--p-space-md) - var(--p-size-2xs) - var(--p-space-3xs)) 50%,calc(100% - var(--p-space-md)) 50%; background-repeat:no-repeat; cursor:pointer; }
.ds select.ds-input:disabled { cursor:not-allowed; }
.ds .ds-input::placeholder { color:var(--p-muted); opacity:var(--p-opacity-full); }
.ds .ds-input:disabled { opacity:var(--p-opacity-full); box-shadow:none; color:var(--p-muted); background:var(--p-disabled); border-color:var(--p-line); cursor:not-allowed; }
.ds .ds-input[aria-invalid="true"] { border-color:var(--p-error); border-width:var(--p-border-width-strong); padding:var(--p-space-xs) var(--p-space-sm); }
.ds label.ds-field { display:grid; gap:var(--p-space-xs); min-width:0; font-size:var(--p-text-body); }
/* looks: 윤곽(box) is the base box; 채움(filled) keeps only a bottom rule on a tinted surface (Material 3 filled text field) */
.ds .ds-input[data-look="filled"] { border-width:0 0 var(--p-border-width-strong); border-radius:var(--p-control-radius) var(--p-control-radius) 0 0; background:var(--p-surface); box-shadow:none; }
.ds .ds-input[data-look="filled"][aria-invalid="true"] { padding:var(--p-space-sm) var(--p-space-md); }
.ds .ds-input[data-look]:disabled { background:var(--p-disabled); border-color:var(--p-line); color:var(--p-muted); box-shadow:none; }
.ds .ds-input[data-look][aria-invalid="true"] { border-color:var(--p-error); }

.ds .ds-button { display:inline-flex; justify-content:center; align-items:center; gap:var(--p-space-xs); min-width:var(--p-control-size-md); min-height:var(--p-control-size-md); padding:var(--p-space-xs) calc(var(--p-space-unit) * 5); border:var(--p-border-width) solid var(--p-accent); border-radius:var(--p-control-radius); background:var(--p-accent); color:var(--p-on-accent); font-size:var(--p-text-body); font-weight:var(--p-weight-semibold); line-height:var(--p-leading-snug); box-shadow:var(--p-control-shadow); text-decoration:none; transition:background var(--p-duration),box-shadow var(--p-duration); }
.ds .ds-button[data-variant="outline"] { border-color:var(--p-control-border); color:var(--p-ink); background:var(--p-surface); box-shadow:var(--p-raised); }
.ds .ds-button[data-variant="ghost"] { color:var(--p-ink); background:transparent; border-color:transparent; box-shadow:none; }
.ds .ds-button[data-size="sm"] { min-height:var(--p-control-size-sm); min-width:var(--p-control-size-sm); padding:var(--p-space-xs) var(--p-space-md); font-size:var(--p-text-sm); }
.ds .ds-button[data-size="lg"] { min-height:var(--p-control-size-lg); min-width:var(--p-control-size-lg); padding:var(--p-space-md) var(--p-space-lg); font-size:var(--p-text-md); }
.ds .ds-button:not(:disabled):is(:hover,[data-state="hover"]) { background:var(--p-accent-shaded); }
.ds .ds-button[data-variant="outline"]:not(:disabled):is(:hover,[data-state="hover"]) { background:var(--p-high); }
.ds .ds-button[data-variant="ghost"]:not(:disabled):is(:hover,[data-state="hover"]) { background:var(--p-disabled); }
.ds .ds-button:not(:disabled):is(:active,[data-state="pressed"]) { box-shadow:var(--p-pressed); }
.ds .ds-button:not([data-variant="primary"]):not(:disabled):is(:active,[data-state="pressed"]) { background:var(--p-bg); box-shadow:var(--p-inset); }
.ds .ds-button[data-state="focus"] { outline:var(--p-border-width-focus) solid var(--p-highlight); outline-offset:var(--p-focus-offset); }
.ds .ds-button:disabled { opacity:var(--p-opacity-full); box-shadow:none; background:var(--p-disabled); border-color:var(--p-line); color:var(--p-muted); }
.ds .ds-button[aria-busy="true"] { background:var(--p-accent); color:var(--p-on-accent); border-color:var(--p-accent); }
.ds .ds-spinner { width:var(--p-size-md); height:var(--p-size-md); flex-shrink:0; border:var(--p-border-width-strong) solid currentColor; border-right-color:transparent; border-radius:var(--p-radius-circle); animation:ds-spin var(--p-duration-spin) var(--p-ease-linear) infinite; }
@keyframes ds-spin { to { transform:rotate(360deg); } }
@media(prefers-reduced-motion:reduce) { .ds .ds-spinner { border-style:var(--p-stroke-dotted); } }
/* looks: 채움(primary) · 윤곽(outline) · 글자(ghost) are the data-variant colour roles above */
.ds .ds-button-count { display:inline-grid; place-items:center; min-width:var(--p-size-lg); height:var(--p-size-lg); padding:0 var(--p-space-xs); border-radius:var(--p-radius-full); background:var(--p-accent); color:var(--p-on-accent); font-size:var(--p-text-sm); font-weight:var(--p-weight-bold); line-height:var(--p-leading-none); }
.ds .ds-button[data-variant="primary"] .ds-button-count { background:var(--p-on-accent); color:var(--p-accent); }

/* Query, status and button share one rounded bar. Labels hidden here stay in the page for screen readers. */
.ds .ds-search-bar { display:grid; grid-template-columns:minmax(0,1fr) auto auto; align-items:center; gap:var(--p-space-2xs); padding:var(--p-space-2xs) var(--p-space-2xs) var(--p-space-2xs) var(--p-space-sm); border:var(--p-border-width) solid var(--p-control-border); border-radius:var(--p-radius-full); background:var(--p-bg); box-shadow:var(--p-inset); }
.ds .ds-search-bar :is(.ds-field > label,.ds-select-field > span) { position:absolute; width:var(--p-size-hairline); height:var(--p-size-hairline); overflow:hidden; clip-path:inset(50%); white-space:nowrap; }
.ds .ds-search-bar .ds-input { border:0; background:transparent; box-shadow:none; }
.ds .ds-search-bar select.ds-input { width:auto; padding-inline:var(--p-space-sm) calc(var(--p-space-sm) * 2 + var(--p-size-2xs) + var(--p-space-3xs)); background-position:calc(100% - var(--p-space-sm) - var(--p-size-2xs) - var(--p-space-3xs)) 50%,calc(100% - var(--p-space-sm)) 50%; border-left:var(--p-border-width) solid var(--p-line); border-radius:0; }
.ds .ds-search-bar > .ds-button { border-radius:var(--p-radius-full); }
@container(max-width:420px) { .ds .ds-search-bar > .ds-button { gap:0; padding-inline:var(--p-space-sm); font-size:0; } }

.ds .ds-chip-group { display:flex; flex-wrap:wrap; gap:var(--p-space-xs); min-width:0; margin:0; padding:0; border:0; }
.ds .ds-chip-group > legend { position:absolute; width:var(--p-size-hairline); height:var(--p-size-hairline); overflow:hidden; clip-path:inset(50%); white-space:nowrap; }
/* Inside a search form the chips take their own row under the query. */
.ds .ds-search-form:has(> .ds-chip-group) { grid-template-columns:minmax(0,1fr) auto; }
.ds .ds-search-form:has(> .ds-chip-group) > .ds-field { grid-column:auto; }
.ds .ds-search-form > .ds-chip-group { grid-column:1/-1; order:3; }

/* The box is hidden; the chosen chip fills and shows a check, never colour alone. */
.ds .ds-chip { position:relative; display:inline-flex; align-items:center; gap:var(--p-space-xs); min-height:var(--p-control-size-sm); padding:0 var(--p-space-md); border:var(--p-border-width) solid var(--p-control-border); border-radius:var(--p-radius-full); background:var(--p-bg); font-size:var(--p-text-body); cursor:pointer; }
.ds .ds-chip input { position:absolute; width:var(--p-size-hairline); height:var(--p-size-hairline); overflow:hidden; clip-path:inset(50%); white-space:nowrap; }
.ds .ds-chip:has(:checked) { border-color:var(--p-accent); background:var(--p-accent); color:var(--p-on-accent); font-weight:var(--p-weight-semibold); }
.ds .ds-chip:has(:checked)::before { content:'✓'; font-weight:var(--p-weight-bold); }
.ds .ds-chip:has(:focus-visible) { outline:var(--p-border-width-focus) solid var(--p-highlight); outline-offset:var(--p-focus-offset); }
.ds .ds-chip:has(:disabled) { border-color:var(--p-line); background:var(--p-disabled); color:var(--p-muted); cursor:not-allowed; }

.ds .ds-card { display:flex; flex-direction:column; height:100%; background:var(--p-surface); border:var(--p-border-width) solid var(--p-line); border-radius:var(--p-radius); box-shadow:var(--p-raised); overflow:hidden; }
.ds .ds-card[data-selected="true"] { border-color:var(--p-success); background:var(--p-selected-surface); }
.ds .ds-card-body { flex:1; padding:var(--p-space-lg); }
.ds .ds-card h3 { font-size:var(--p-text-title); line-height:var(--p-leading-snug); font-weight:var(--p-weight-semibold); letter-spacing:var(--p-tracking-tighter); margin-top:var(--p-space-md); }
.ds .ds-card p { font-size:var(--p-text-body); color:var(--p-muted); margin-top:var(--p-space-xs); }
.ds .ds-card-actions { display:flex; justify-content:flex-end; padding:var(--p-space-md) var(--p-space-lg); }
/* Looks (Material 3 elevated · filled · outlined): :where keeps each look as weak as the base rule, so a selected card still shows its selected state. */
.ds .ds-card:where([data-look="filled"]) { border-color:transparent; background:var(--p-tile); box-shadow:none; }
.ds .ds-card:where([data-look="outlined"]) { background:var(--p-bg); box-shadow:none; }

/* results as rows instead of tiles */
.ds .ds-result-list { grid-template-columns:minmax(0,1fr); gap:0; border-top:var(--p-border-width) solid var(--p-line); }
.ds .ds-result-list .ds-card { flex-flow:row wrap; align-items:center; border:0; border-bottom:var(--p-border-width) solid var(--p-line); border-radius:0; background:transparent; box-shadow:none; }
.ds .ds-result-list .ds-card-body { flex:1 1 calc(var(--p-space-unit) * 40); padding:var(--p-space-md) 0; }
.ds .ds-result-list .ds-card h3 { margin-top:var(--p-space-2xs); font-size:var(--p-text-md); }
.ds .ds-result-list .ds-divider { display:none; }
.ds .ds-result-list .ds-card-actions { padding:var(--p-space-xs) 0 var(--p-space-xs) var(--p-space-sm); }

/* One markup, five shapes. Selection never rests on color alone: each shape adds a mark, a tile, a pill, a press or weight. */
/* Floating shapes declare --ds-bottom-nav-offset so a screen frame can keep them off the edges. */
.ds .ds-bottom-nav { position:relative; isolation:isolate; display:flex; justify-content:space-around; align-items:center; gap:var(--p-space-2xs); padding:var(--p-space-xs); background:var(--p-surface); border-top:var(--p-border-width) solid var(--p-line); }
.ds .ds-bottom-nav > :not(.ds-bottom-nav-create) { position:relative; display:flex; flex:1; min-width:var(--p-control-size-sm); min-height:var(--p-control-size-xl); flex-direction:column; justify-content:center; align-items:center; gap:var(--p-space-2xs); padding:var(--p-space-xs); border:0; color:var(--p-muted); background:transparent; font-size:var(--p-text-sm); text-decoration:none; }
.ds .ds-bottom-nav > :is([aria-pressed="true"],[aria-current="page"]) { color:var(--p-ink); font-weight:var(--p-weight-extrabold); }
.ds .ds-bottom-nav > :not(.ds-bottom-nav-create)::before,.ds .ds-bottom-nav > :not(.ds-bottom-nav-create)::after { content:''; position:absolute; pointer-events:none; }
.ds .ds-bottom-nav > .ds-bottom-nav-create { display:grid; place-items:center; flex:none; width:var(--p-control-size-md); height:var(--p-control-size-md); padding:0; border:0; border-radius:var(--p-radius-circle); color:var(--p-on-accent); background:var(--p-accent); box-shadow:var(--p-raised); }
.ds .ds-bottom-nav > .ds-bottom-nav-create .ui-icon { width:var(--p-icon-lg); height:var(--p-icon-lg); }
/* 05 line: top bar (also the look without a variant) */
.ds .ds-bottom-nav:is(:not([data-variant]),[data-variant="line"]) > :is([aria-pressed="true"],[aria-current="page"])::before { top:calc(var(--p-space-xs) * -1); left:calc(100% / 6); right:calc(100% / 6); height:var(--p-size-2xs); border-radius:0 0 var(--p-radius-sm) var(--p-radius-sm); background:var(--p-accent); }
/* 01 minimal: flat, dot under the label */
.ds .ds-bottom-nav[data-variant="minimal"] { background:var(--p-bg); border-top-color:transparent; }
.ds .ds-bottom-nav[data-variant="minimal"] > :is([aria-pressed="true"],[aria-current="page"])::after { bottom:var(--p-space-3xs); width:var(--p-size-2xs); height:var(--p-size-2xs); border-radius:var(--p-radius-circle); background:var(--p-accent); }
/* 02 glass: translucent edge bar over the screen, light tile on the chosen item */
.ds .ds-bottom-nav[data-variant="glass"] { background:var(--p-high); border-top-color:var(--p-line); }
@supports(backdrop-filter:blur(0)) { .ds .ds-bottom-nav[data-variant="glass"] { background:var(--p-glass-veil); backdrop-filter:var(--p-blur-glass); } }
.ds .ds-bottom-nav[data-variant="glass"] > :not(.ds-bottom-nav-create) { border-radius:var(--p-radius-xl); }
.ds .ds-bottom-nav[data-variant="glass"] > :is([aria-pressed="true"],[aria-current="page"]) { background:var(--p-high-veil); box-shadow:inset 0 0 0 var(--p-border-width) var(--p-line); }
/* 03 float: floating capsule, create button inside, soft disc behind the chosen icon */
.ds .ds-bottom-nav[data-variant="float"] { --ds-bottom-nav-offset:var(--p-space-sm); padding:var(--p-space-xs) var(--p-space-xs); border:var(--p-border-width) solid var(--p-line); border-radius:var(--p-radius-full); background:var(--p-high); box-shadow:var(--p-shadow); }
.ds .ds-bottom-nav[data-variant="float"] > :not(.ds-bottom-nav-create) { min-height:var(--p-control-size-lg); }
.ds .ds-bottom-nav[data-variant="float"] > :is([aria-pressed="true"],[aria-current="page"])::before { top:var(--p-space-2xs); left:50%; width:calc(var(--p-space-unit) * 9); height:var(--p-size-xl); margin-left:calc((var(--p-space-md) + var(--p-space-3xs)) * -1); border-radius:var(--p-radius-xl); background:var(--p-soft); z-index:var(--p-layer-below); }
/* 04 pill: only the chosen item shows its name, inside a soft pill */
.ds .ds-bottom-nav[data-variant="pill"] { padding:var(--p-space-xs) var(--p-space-xs); background:var(--p-bg); }
.ds .ds-bottom-nav[data-variant="pill"] > :not(.ds-bottom-nav-create) { min-height:var(--p-control-size-sm); flex-direction:row; gap:var(--p-space-xs); border-radius:var(--p-radius-full); }
.ds .ds-bottom-nav[data-variant="pill"] > :not([aria-pressed="true"],[aria-current="page"]) > span { position:absolute; width:var(--p-size-hairline); height:var(--p-size-hairline); overflow:hidden; clip-path:inset(50%); white-space:nowrap; }
.ds .ds-bottom-nav[data-variant="pill"] > :is([aria-pressed="true"],[aria-current="page"]) { flex:1.8; padding:var(--p-space-xs) var(--p-space-md); background:var(--p-soft); font-size:var(--p-text-sm); }
@media(prefers-reduced-transparency:reduce) { .ds .ds-bottom-nav[data-variant="glass"] { background:var(--p-high); backdrop-filter:none; } }

'use client';
import React, { useEffect, useRef, useState } from 'react';
import { Template } from './template.jsx';
import { SearchForm } from './search-form.jsx';
import { SearchBar } from './search-bar.jsx';
import { FilterChipRow } from './filter-chip-row.jsx';
import { ResultGrid } from './result-grid.jsx';
import { ResultList } from './result-list.jsx';
import { EmptyState } from './empty-state.jsx';
import { Button } from './button.jsx';
const defaults = [{ id: 'spring', title: '봄의 색', description: '연한 초록과 따뜻한 노랑', tag: '진행 중' }, { id: 'weekend', title: '주말의 기록', description: '산책하며 모은 장면들', tag: '완료' }, { id: 'studio', title: '작은 작업실', description: '다음 프로젝트의 첫 아이디어', tag: '진행 중' }];
// Each screen look brings the bottom bar shape and the search blocks that suit it, the same pairs the HTML renderer uses.
// search: grid (form + result grid), bar (search bar + result grid), list (form + result list), chips (form with a filter-chip row + result grid).
// Pass a <BottomNav variant={pageLooks[look].navigation} /> as navigation to complete the screen.
export const pageLooks = { stack: { navigation: 'minimal', search: 'grid' }, hero: { navigation: 'pill', search: 'bar' }, appbar: { navigation: 'line', search: 'list' }, sheet: { navigation: 'glass', search: 'chips' }, dashboard: { navigation: 'float', search: 'list' } };
// The collection search composed from the small blocks, plus the record detail it opens. onSave(record) may be async and may throw.
export function CollectionSearch({ records = defaults, onSave, search = 'grid' }) {
  const form = useRef(null); const opener = useRef(null); const detail = useRef(null);
  const [filter, setFilter] = useState({ query: '', status: 'all' }); const [selected, setSelected] = useState(null); const [saved, setSaved] = useState([]);
  const pending = useRef(new Set());
  const [pendingIds, setPendingIds] = useState([]);
  const [messages, setMessages] = useState({});
  const busy = selected ? pendingIds.includes(selected.id) : false;
  const message = selected ? messages[selected.id] || '' : '';
  const filtered = records.filter(item => filter.query.toLocaleLowerCase().split(/\s+/).every(term => `${item.title} ${item.description}`.toLocaleLowerCase().includes(term)) && (filter.status === 'all' || item.tag === filter.status));
  useEffect(() => { if (selected) detail.current?.focus(); else opener.current?.focus(); }, [selected]);
  function open(item, event) { opener.current = event.currentTarget; setSelected(item); }
  async function save() {
    const record = selected;
    if (!record || pending.current.has(record.id)) return;
    pending.current.add(record.id);
    setPendingIds([...pending.current]);
    setMessages(old => ({ ...old, [record.id]: '' }));
    try {
      await onSave?.(record);
      setSaved(old => [...new Set([...old, record.id])]);
      setMessages(old => ({ ...old, [record.id]: '보관했어요.' }));
    } catch {
      setMessages(old => ({ ...old, [record.id]: '보관하지 못했어요. 다시 시도해 주세요.' }));
    } finally {
      pending.current.delete(record.id);
      setPendingIds([...pending.current]);
    }
  }
  const query = () => form.current.elements.query.value.trim();
  const status = next => setFilter({ query: query(), status: next });
  const Form = search === 'bar' ? SearchBar : SearchForm;
  const Results = search === 'list' ? ResultList : ResultGrid;
  const chips = search === 'chips' ? <FilterChipRow name="status" onValueChange={status} /> : undefined;
  return <section className="ds-search-module" aria-label="컬렉션 검색"><div hidden={!!selected}><Form formRef={form} onSearch={setFilter} onStatusChange={event => status(event.target.value)} filter={chips} /><Results records={filtered} onAction={open} />{!filtered.length && <EmptyState onAction={() => { form.current.reset(); setFilter({ query: '', status: 'all' }); form.current.elements.query.focus(); }} />}</div>{selected && <section ref={detail} className="ds-record-detail" aria-label="컬렉션 상세" tabIndex={-1}><h3>{selected.title}</h3><p>{selected.description}</p><div><Button variant="outline" onClick={() => setSelected(null)}>목록으로</Button><Button loading={busy} aria-pressed={saved.includes(selected.id)} onClick={save}>{saved.includes(selected.id) ? '보관됨' : '컬렉션에 보관'}</Button></div><p role="status">{message}</p></section>}</section>;
}
export function CollectionPage({ title = '컬렉션', records, onSave, look = 'stack', navigation }) {
  const pair = pageLooks[look] ?? pageLooks.stack;
  const list = records ?? defaults;
  const summary = [['전체', `${list.length}개`], ...['진행 중', '완료'].map(tag => [tag, `${list.filter(item => item.tag === tag).length}개`])];
  return <Template title={title} count={`${list.length}개`} look={pageLooks[look] ? look : 'stack'} summary={summary} navigation={navigation}><CollectionSearch records={list} onSave={onSave} search={pair.search} /></Template>;
}

import React from 'react';
