  return <fieldset className="ds-chip-group"><legend>{legend}</legend>{items.map(([key, label]) => <FilterChip key={key} type="radio" name={name} value={key} {...own(key)} onChange={() => onValueChange?.(key)}>{label}</FilterChip>)}</fieldset>;
}

